-- Additive proposal, generated by Supabase CLI 3.0.0. Historical migrations
-- and encrypted credentials remain unchanged. No provider is contacted.
alter table private.gmail_connections
  add column sync_lease_id uuid,
  add column sync_lease_actor uuid references auth.users(id) on delete restrict;

-- Keep existing status reads; the newly added worker capability is server-only.
revoke select on private.gmail_connections from authenticated;
grant select(organization_id,connected_by,google_subject,email,status,connected_at,
  last_sync_at,sync_lease_until,sync_page_token) on private.gmail_connections to authenticated;

-- Every successful authorization (including the same mailbox) supersedes
-- old workers. The connection write and token replacement are one transaction.
create function private.tc_gmail_reset_sync_lease() returns trigger
language plpgsql security invoker set search_path='' as $$
begin
  new.sync_lease_id:=null;
  new.sync_lease_actor:=null;
  new.sync_lease_until:=null;
  return new;
end;
$$;
revoke all on function private.tc_gmail_reset_sync_lease() from public,anon,authenticated;
create trigger gmail_reconnect_resets_sync_lease
  before update of connected_at,connected_by,google_subject on private.gmail_connections
  for each row execute function private.tc_gmail_reset_sync_lease();

create function private.tc_gmail_sync_fenced(p_action text,p_data jsonb) returns jsonb
language plpgsql security definer set search_path='' as $$
declare
  org uuid:=nullif(p_data->>'organization_id','')::uuid;
  actor uuid:=nullif(p_data->>'user_id','')::uuid;
  lease uuid:=nullif(p_data->>'sync_lease_id','')::uuid;
  c private.gmail_connections;
  access jsonb;
  current_lease boolean;
  permitted boolean;
begin
  if org is null or actor is null or lease is null or p_action not in
    ('lock_sync','assert_sync','credentials','exists','reserve_ai','record_invoice','finish_sync')
    then raise exception 'Importación de correo no válida' using errcode='22023';end if;
  -- Serialize connect/disconnect, lease acquisition and document commit using
  -- this exact company connection row. No lock survives the database call.
  select * into c from private.gmail_connections where organization_id=org for update;
  current_lease:=found and c.sync_lease_id=lease and c.sync_lease_actor=actor
    and c.sync_lease_until>now() and c.status='connected';
  access:=private.tc_organization_access_for(org,actor);
  permitted:=coalesce((access->>'active')::boolean,false)
    and coalesce((access->>'can_write')::boolean,false)
    and coalesce((access->'features'->>'gmail')::boolean,false)
    and exists(select 1 from auth.users u where u.id=actor and u.email_confirmed_at is not null
      and (to_jsonb(u)->>'deleted_at') is null
      and coalesce((to_jsonb(u)->>'banned_until')::timestamptz,'-infinity')<=now());
  if p_action='lock_sync' then
    if not permitted or c.organization_id is null or c.status<>'connected'
      or (c.sync_lease_until is not null and c.sync_lease_until>=now()) then return 'false'::jsonb;end if;
    update private.gmail_connections set sync_lease_id=lease,sync_lease_actor=actor,
      sync_lease_until=now()+interval '5 minutes' where organization_id=org;
    return 'true'::jsonb;
  elsif p_action='assert_sync' then
    return to_jsonb(coalesce(current_lease and permitted,false));
  elsif p_action='finish_sync' then
    -- A stale worker has no authority over the replacement connection or
    -- another worker's lease, cursor, last_sync_at or reauthorization status.
    if not coalesce(current_lease,false) then return '{}'::jsonb;end if;
    update private.gmail_connections set sync_lease_until=null,sync_lease_id=null,sync_lease_actor=null,
      last_sync_at=case when permitted and p_data->>'succeeded'='true' then now() else last_sync_at end,
      sync_page_token=case when permitted and p_data->>'succeeded'='true' then nullif(p_data->>'page_token','') else sync_page_token end,
      status=case when permitted and p_data->>'reauthorize'='true' then 'reauthorize' else status end
      where organization_id=org;
    return '{}'::jsonb;
  end if;
  if not coalesce(current_lease and permitted,false) then
    raise exception 'La importación de correo ha sido sustituida' using errcode='42501';end if;
  if p_action='credentials' then return private.tc_gmail_credentials(p_data);end if;
  if p_action='exists' then return private.tc_gmail_sync(p_action,p_data);end if;
  if p_action='reserve_ai' and not coalesce((access->'features'->>'invoice_ai')::boolean,false)
    then return 'false'::jsonb;end if;
  -- The lease row stays locked throughout the insert: a reconnect cannot
  -- commit between permission validation and the private document write.
  return private.tc_gmail_invoices(p_action,p_data);
end;
$$;
revoke all on function private.tc_gmail_sync_fenced(text,jsonb) from public,anon,authenticated;

-- Preserve the existing service-only RPC, OID and ACL. Native v19 always sends
-- a fresh lease UUID; older internal consumers retain their historic contract.
-- Legacy finish calls cannot release or overwrite a new fenced worker.
create or replace function public.gmail_server(p_action text,p_data jsonb) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare c private.gmail_connections;
begin
  if p_data ? 'sync_lease_id' then return private.tc_gmail_sync_fenced(p_action,p_data);end if;
  if p_action in ('lock_sync','finish_sync') then
    select * into c from private.gmail_connections
      where organization_id=(p_data->>'organization_id')::uuid for update;
    if p_action='lock_sync' then
      if c.organization_id is null or c.status<>'connected'
        or (c.sync_lease_until is not null and c.sync_lease_until>=now()) then return 'false'::jsonb;end if;
      -- A legacy acquisition replaces, rather than revives, an expired UUID.
      update private.gmail_connections set sync_lease_until=now()+interval '5 minutes',
        sync_lease_id=null,sync_lease_actor=null where organization_id=c.organization_id;
      return 'true'::jsonb;
    elsif c.organization_id is null or c.sync_lease_id is not null or c.sync_lease_until is null then
      return '{}'::jsonb;
    end if;
    -- Keep the row lock until the legacy update completes: the guard and write
    -- cannot straddle a reconnect or a new fenced worker.
    return private.tc_gmail_sync(p_action,p_data);
  end if;
  if p_action in ('state_create','state_consume','pending_create','pending_consume') then return private.tc_gmail_state(p_action,p_data);end if;
  if p_action in ('connect','credentials','disconnect') then return private.tc_gmail_connection(p_action,p_data);end if;
  if p_action in ('lock_sync','finish_sync','exists') then return private.tc_gmail_sync(p_action,p_data);end if;
  if p_action in ('reserve_ai','record_invoice') then return private.tc_gmail_invoices(p_action,p_data);end if;
  raise exception 'Unsupported internal operation';
end;
$$;
revoke all on function public.gmail_server(text,jsonb) from public,anon,authenticated;
do $$ begin if exists(select 1 from pg_roles where rolname='service_role') then
  grant execute on function private.tc_gmail_sync_fenced(text,jsonb) to service_role;
  grant execute on function public.gmail_server(text,jsonb) to service_role;
end if;end $$;
